type Line = 'viral_presets' | 'ai_presets' | 'mv_templates';
interface FormRow { code: string; nameEn: string; nameZh: string; executorKey: string; inputSchema: Record<string, unknown>; uiSchema: Record<string, unknown>; outputSchema: Record<string, unknown>; enabled: boolean }
interface ModelRow { code: string; label: string; provider: string; exactModel: string; capability: string; defaultParams: Record<string, unknown>; allowedParams: string[]; enabled: boolean }
interface VersionRow { id: string; versionNumber: number; status: string; nameEn: string; nameZh?: string; descriptionEn?: string; descriptionZh?: string; coverUrl: string; previewVideoUrl: string; source?: string | null; modelCode?: string | null; priceCredits: number; inputSchema: Record<string, unknown>; uiSchema: Record<string, unknown>; executionConfig: Record<string, unknown> }
interface ProductRow { id: string; slug: string; line: Line; formCode: string; status: string; featured: boolean; sortOrder: number; currentVersionId?: string | null; versions: VersionRow[] }
interface TaskRow { id: string; userId: string; status: string; stage: string; productLine: string; quoteCredits: number; providerTaskId?: string | null; errorMessage?: string | null; createdAt: string }
